PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS visits (id INTEGER PRIMARY KEY AUTOINCREMENT, appointment_date TEXT NOT NULL, appointment_time TEXT NOT NULL, provider TEXT NOT NULL, specialty TEXT NOT NULL, reason TEXT NOT NULL, location TEXT, notes TEXT, brief_confirmed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS preparation_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL, UNIQUE(visit_id,title), FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS symptoms (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL, name TEXT NOT NULL, onset TEXT, severity INTEGER, frequency TEXT, pattern TEXT, triggers TEXT, relief TEXT, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE, CHECK(severity IS NULL OR severity BETWEEN 0 AND 10));
CREATE TABLE IF NOT EXISTS medications (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL, name TEXT NOT NULL, dose TEXT, frequency TEXT, notes TEXT, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS allergies (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL, allergy TEXT NOT NULL, reaction TEXT, notes TEXT, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL, title TEXT NOT NULL, filename TEXT, mime_type TEXT, extracted_text TEXT NOT NULL, suggested_category TEXT, confidence REAL, category TEXT, category_confirmed INTEGER NOT NULL DEFAULT 0, extraction_status TEXT NOT NULL DEFAULT 'ready', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL, question TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE);
